"""Validate, stage and publish the generator's owned files."""
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import tempfile

MANIFEST = 'generated-manifest.json'
OWNER = 'zipzi-python2/tools/generate.py'
HEADERS = ('# @generated by zipzi-python2/tools/generate.py; DO NOT EDIT.\n',
           '// @generated by zipzi-python2/tools/generate.py; DO NOT EDIT.\n')
DIRECTORIES = ('client/python/zipzi/_generated/', 'src/generated/',
               'schema/types/', 'client/python/zipzi/docs/reference/',
               'client/python/zipzi/modeling/')


def sha(data):
    return hashlib.sha256(data).hexdigest()


def safe_path(package, path, fixed):
    if not isinstance(path, str):
        raise ValueError('Invalid generated path')
    parts = PurePosixPath(path)
    if (parts.is_absolute() or not parts.parts or parts.as_posix() != path
            or any(part in {'.', '..'} for part in parts.parts)
            or not (path in fixed or any(path.startswith(prefix) for prefix in DIRECTORIES))):
        raise ValueError(f'Unowned generated path: {path}')
    file = package.joinpath(*parts.parts)
    if any(package.joinpath(*parts.parts[:i]).is_symlink() for i in range(1, len(parts.parts) + 1)):
        raise ValueError(f'Generated path traverses a symlink: {path}')
    if not file.resolve().is_relative_to(package.resolve()):
        raise ValueError(f'Generated path outside package: {path}')
    return file


def marked(path, data):
    if path.endswith('.json'):
        try:
            return json.loads(data).get('_generated_by') == OWNER
        except (ValueError, AttributeError, UnicodeDecodeError):
            return False
    return data.startswith(tuple(header.encode() for header in HEADERS))


def manifest_bytes(output):
    entries = [{'path': path, 'owner': OWNER, 'sha256': sha(content.encode('utf-8'))}
               for path, content in sorted(output.items())]
    return (json.dumps({'version': 1, 'files': entries}, indent=2) + '\n').encode()


def read_manifest(package, fixed):
    file = package / MANIFEST
    if file.is_symlink():
        raise ValueError('Manifest is a symlink')
    if not file.exists():
        return None
    try:
        value = json.loads(file.read_bytes())
        if value['version'] != 1 or not isinstance(value['files'], list):
            raise ValueError('Invalid manifest')
        result = {}
        for entry in value['files']:
            path, owner, digest = entry['path'], entry['owner'], entry['sha256']
            safe_path(package, path, fixed)
            if path in result or owner != OWNER or not isinstance(digest, str) or len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
                raise ValueError('Invalid manifest entry')
            result[path] = digest
        return result
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('Invalid generated manifest') from exc


def write_outputs(output, check, package, fixed):
    package = Path(package)
    paths = {path: safe_path(package, path, fixed) for path in output}
    old = read_manifest(package, fixed)
    if old is None and any(path not in fixed and file.exists() for path, file in paths.items()):
        raise ValueError('Cannot bootstrap ownership outside the existing generated targets')
    # Never silently adopt files in generator-owned directories.
    for folder in ('client/python/zipzi/_generated', 'src/generated', 'schema/types',
                   'client/python/zipzi/docs/reference', 'client/python/zipzi/modeling'):
        base = package / folder
        if base.is_symlink():
            raise ValueError(f'Generated directory is a symlink: {base}')
        for file in base.rglob('*'):
            path = file.relative_to(package).as_posix()
            if '__pycache__' in file.parts:
                continue
            if file.is_symlink():
                raise ValueError(f'Generated path is a symlink: {path}')
            if file.is_file() and path not in output and (old is None or path not in old):
                raise ValueError(f'Unmanaged file in generated directory: {file}')
    differences = []
    for path, file in paths.items():
        if not isinstance(output[path], str) or not marked(path, output[path].encode()):
            raise ValueError(f'Invalid generated content: {path}')
        existing = file.read_bytes() if file.is_file() else None
        if existing is not None and not marked(path, existing):
            raise ValueError(f'Refusing to overwrite handwritten file: {path}')
        if existing is not None and old is not None and path not in old:
            raise ValueError(f'Refusing to adopt unknown file: {path}')
        if existing != output[path].encode('utf-8'):
            differences.append(path)
    stale = sorted(set(old or ()) - set(output))
    for path in stale:
        file = safe_path(package, path, fixed)
        if file.exists():
            data = file.read_bytes()
            if not check and (not marked(path, data) or sha(data) != old[path]):
                raise ValueError(f'Refusing to delete modified generated file: {path}')
            differences.append(path)
    desired_manifest = manifest_bytes(output)
    manifest = package / MANIFEST
    if not manifest.is_file() or manifest.read_bytes() != desired_manifest:
        differences.append(MANIFEST)
    if check:
        return differences
    # Render everything into a private staging directory before replacing any file.
    package.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.zipzi-generated-', dir=package) as tmp:
        stage = Path(tmp)
        for path in differences:
            if path == MANIFEST or path in stale:
                continue
            destination = stage / path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(output[path].encode('utf-8'))
        staged_manifest = stage / MANIFEST
        staged_manifest.write_bytes(desired_manifest)
        for path in differences:
            if path == MANIFEST or path in stale:
                continue
            paths[path].parent.mkdir(parents=True, exist_ok=True)
            os.replace(stage / path, paths[path])
        for path in stale:
            file = safe_path(package, path, fixed)
            if file.exists():
                file.unlink()
        os.replace(staged_manifest, manifest)
    return differences
